		The method \eqref{CHNS1}--\eqref{CHNS5} is unconditionally long-time stable in the sense that for any $N\geq 2$
		\begin{align*}
			&
			\lambda \Vert \nabla \phi_{N}\Vert^2
			+\frac{\lambda\eta^2}{2} \Vert q_{N}\Vert^2
			+\Vert u_{N}\Vert^2
			\\
			&
			+\frac{\lambda}{2\theta+1} \sum_{n=1}^{N-1}\| \nabla(\phi_{n+1}- 2 \phi_n+\phi_{n-1})\|^2_F
			+\frac{\lambda\eta^2}{2(2\theta+1)}\sum_{n=1}^{N-1} \| q_{n+1}- 2 q_n+q_{n-1}\|^2_F
			\nonumber\\
			&
			+\frac{1}{2\theta+1} \sum_{n=1}^{N-1}\| u_{n+1}- 2 u_n+u_{n-1}\|^2_F
			+\frac{4 \Delta t\nu}{2\theta+1} \sum_{n=1}^{N-1}\Vert\nabla {\@fontswitch{\relax}{\mathcal} J}^{\epsilon}_{n+\theta}(u)\Vert^2
			+\frac{4\Delta t M }{2\theta+1}\sum_{n=1}^{N-1} \Vert \nabla {\@fontswitch{\relax}{\mathcal} H}_{n+\theta}(\mu)\Vert^2
			\nonumber\\
			&
			\leq \left(\frac{2\theta  -1 }{2\theta + 1}\right)^N \left( \lambda \Vert \nabla \phi_{0}\Vert^2
			+\frac{\lambda\eta^2}{2} \Vert q_{0}\Vert^2
			+\Vert u_{0}\Vert^2 \right)
			\nonumber\\
			&\qquad
			+2(1-\left(\frac{2\theta  -1 }{2\theta + 1}\right)^N) \left(\lambda {\left\| \left[ \begin{matrix} \nabla \phi_{1}\cr \nabla \phi_{0} \end{matrix} \right]\right\|} ^2_G
			+\frac{\lambda\eta^2}{2} {\left\| \left[ \begin{matrix} q_{1}\cr q_{0} \end{matrix} \right]\right\|} ^2_G
			+{\left\| \left[ \begin{matrix} u_{1}\cr u_{0} \end{matrix} \right]\right\|} ^2_G \right). \nonumber
		\end{align*}
